435	+/* read_ns: one clock in nanoseconds; 0 or the errno (EOVERFLOW if bad). */
436	+static int read_ns(const capture_env *env, capture_clock clock,
437	+                   int64_t *out)
438	+{
439	+    struct timespec ts;
440	+    int err = env->read_clock(env->ctx, clock, &ts);
441	+
442	+    if (err != 0) {
443	+        return err;
444	+    }
445	+    if (ts.tv_sec < 0 || ts.tv_nsec < 0 || ts.tv_nsec >= NSEC_PER_SEC ||
