466	+static int append(capture_store *st, const storage_record *rec,
467	+                  uint64_t now_ns)
468	+{
469	+    size_t before = st->writer.buffered_records;
470	+    storage_log_result r = storage_log_append(&st->writer, rec, now_ns);
471	+    int err;
472	+
473	+    if (r.status != STORAGE_LOG_OK) {
474	+        return log_store_error(st, "append", r);
475	+    }
476	+    st->records_appended++;
477	+    line_start(st, "stored");
478	+    fprintf(st->log, " type=%s sequence=%" PRIu64 " source_sequence=%"
479	+            PRIu32 " valid=%d buffered=%zu\n", type_name(rec->record_type),
480	+            rec->sequence, rec->source_sequence,
481	+            (rec->flags & STORAGE_FLAG_VALID) != 0,
482	+            st->writer.buffered_records);
483	+    err = finish(st->log);
484	+    if (err == 0 && st->writer.buffered_records == 0) {
485	+        err = log_flushed(st, before + 1,
486	+                          before + 1 == STORAGE_LOG_BATCH_RECORDS
487	+                              ? "batch_full" : "deadline");
488	+    }
489	+    return err;
490	+}
