500	+    int64_t mono_ns = 0;
501	+    int wall_err;
502	+    int mono_err;
503	+    int trust_err = 0;
504	+    capture_clock_trust trust;
505	+    size_t before;
506	+    int err;
507	+
508	+    memset(st, 0, sizeof *st);
509	+    st->log = log;
510	+    st->env = env;
511	+    st->sensor = cfg->sensor;
512	+    st->simulated = env->is_simulated;
513	+    st->tick_period_ns = cfg->tick_period_ns;
