517	+    r = storage_log_open(&st->writer, dir_path, name, 1, st->simulated);
518	+    if (r.status != STORAGE_LOG_OK) {
519	+        return log_store_error(st, "open", r);
520	+    }
521	+    line_start(st, "store_open");
522	+    fprintf(st->log, " dir=%s file=%s first_sequence=1 "
523	+            "sequence_scope=this_process_only\n", dir_path, name);
524	+    err = finish(st->log);
525	+    if (err != 0) {
526	+        goto fail;
527	+    }
528	+
529	+    wall_err = read_ns(env, CAPTURE_CLOCK_WALL, &wall_ns);
530	+    mono_err = read_ns(env, CAPTURE_CLOCK_MONOTONIC, &mono_ns);
531	+    trust = env->check_clock_trust(env->ctx, &trust_err);
532	+    if (wall_err != 0 || mono_err != 0) {
533	+        /* Logged, not fatal: START is stored with TIME_UNAVAILABLE. */
