537	+    if (trust == CAPTURE_CLOCK_TRUST_UNKNOWN) {
538	+        (void)log_clock_error(st, "start_clock_trust", trust_err);
539	+    }
540	+    storage_record_start(st->writer.next_sequence, st->simulated, wall_ns,
541	+                         wall_err, mono_ns, mono_err, trust, &start);
542	+    err = append(st, &start, mono_err == 0 ? (uint64_t)mono_ns : 0);
