572	+    int err;
573	+
574	+    err = capture_log_sample(st->log, sample);
575	+    if (err != 0) {
576	+        return err;
577	+    }
578	+    err = read_ns(st->env, CAPTURE_CLOCK_MONOTONIC, &now_ns);
579	+    if (err != 0) {
580	+        return log_clock_error(st, "append_clock", err);
