586	+/*
587	+ * capture_store_emit_heartbeat: log the heartbeat, then flush the batch if
588	+ * it would be overdue by the next tick's heartbeat.
589	+ */
590	+int capture_store_emit_heartbeat(void *ctx,
591	+                                 const capture_heartbeat *heartbeat)
592	+{
593	+    capture_store *st = ctx;
594	+    storage_log_result r;
595	+    size_t before;
596	+    int64_t now_ns;
597	+    uint64_t next_tick_ns;
598	+    int err;
599	+
600	+    err = capture_log_heartbeat(st->log, heartbeat);
601	+    if (err != 0) {
602	+        return err;
603	+    }
604	+    before = st->writer.buffered_records;
605	+    if (before == 0) {
606	+        return 0;
607	+    }
608	+    err = read_ns(st->env, CAPTURE_CLOCK_MONOTONIC, &now_ns);
609	+    if (err != 0) {
610	+        return log_clock_error(st, "flush_clock", err);
611	+    }
612	+    next_tick_ns = (uint64_t)now_ns;
613	+    if (UINT64_MAX - next_tick_ns >= (uint64_t)st->tick_period_ns) {
614	+        next_tick_ns += (uint64_t)st->tick_period_ns;
615	+    } else {
616	+        next_tick_ns = UINT64_MAX;
617	+    }
618	+    r = storage_log_flush_if_due(&st->writer, next_tick_ns);
619	+    if (r.status != STORAGE_LOG_OK) {
620	+        return log_store_error(st, "flush_if_due", r);
621	+    }
622	+    if (st->writer.buffered_records == 0) {
623	+        return log_flushed(st, before, "deadline");
624	+    }
625	+    return 0;
626	+}
