628	+/* capture_store_close: see capture_store.h. */
629	+int capture_store_close(capture_store *st)
630	+{
631	+    size_t before = st->writer.buffered_records;
632	+    storage_log_result r = storage_log_close(&st->writer);
633	+
634	+    if (r.status != STORAGE_LOG_OK) {
635	+        return log_store_error(st, "close", r);
636	+    }
637	+    line_start(st, "store_close");
638	+    fprintf(st->log, " flushed_records=%zu records_appended=%" PRIu64
639	+            " file_bytes=%" PRIu64 " result=OK\n", before,
640	+            st->records_appended, st->writer.file_size_bytes);
641	+    return finish(st->log);
642	+}
