785	+
786	+/* stored_errno: errno as u16, or 0xFFFF when it does not fit. */
787	+static uint16_t stored_errno(int err)
788	+{
789	+    if (err < 0 || err > 0xFFFF) {
790	+        return STORAGE_ERRNO_UNREPRESENTABLE;
791	+    }
792	+    return (uint16_t)err;
793	+}
794	+
795	+/* storage_record_from_sample: see capture_record.h. */
796	+void storage_record_from_sample(const capture_sample *s, uint64_t sequence,
797	+                                storage_record *rec)
798	+{
799	+    int unavailable = 0;
800	+
801	+    memset(rec, 0, sizeof *rec);
802	+    rec->record_type = s->sensor == CAPTURE_SENSOR_LIGHT
803	+                           ? STORAGE_RECORD_TYPE_LIGHT
804	+                           : STORAGE_RECORD_TYPE_SOIL;
805	+    rec->sequence = sequence;
806	+    rec->wall_clock_ns = stored_time(s->wall_ns, s->wall_errno, &unavailable);
807	+    rec->monotonic_ns = stored_time(s->mono_ns, s->mono_errno, &unavailable);
808	+    rec->flags = time_flags(s->clock_trust, unavailable);
809	+    if (s->is_simulated) {
810	+        rec->flags |= STORAGE_FLAG_SIMULATED;
811	+    }
812	+    rec->source_sequence = s->sequence;
813	+    if (s->valid) {
814	+        rec->flags |= STORAGE_FLAG_VALID;
815	+        rec->sensor_value = s->value;
816	+        return;
817	+    }
818	+    if (s->sensor == CAPTURE_SENSOR_SOIL && s->has_rejected_value) {
819	+        rec->sensor_value = s->rejected_value;
820	+    }
821	+    rec->i2c_status = (uint8_t)s->io.status;
822	+    rec->failure_stage = (uint8_t)s->stage;
823	+    rec->os_errno = stored_errno(s->io.os_errno);
824	+}
825	+
826	+/* storage_record_start: see capture_record.h. */
827	+void storage_record_start(uint64_t sequence, int simulated,
828	+                          int64_t wall_ns, int wall_errno,
829	+                          int64_t mono_ns, int mono_errno,
830	+                          capture_clock_trust trust, storage_record *rec)
831	+{
832	+    int unavailable = 0;
833	+
834	+    memset(rec, 0, sizeof *rec);
835	+    rec->record_type = STORAGE_RECORD_TYPE_START;
836	+    rec->sequence = sequence;
837	+    rec->wall_clock_ns = stored_time(wall_ns, wall_errno, &unavailable);
838	+    rec->monotonic_ns = stored_time(mono_ns, mono_errno, &unavailable);
839	+    rec->flags = time_flags(trust, unavailable);
840	+    if (simulated) {
841	+        rec->flags |= STORAGE_FLAG_SIMULATED;
842	+    }
843	+}
844	diff --git a/src/storage/storage_dump_main.c b/src/storage/storage_dump_main.c
845	new file mode 100644
846	index 0000000..8073440
847	--- /dev/null
848	+++ b/src/storage/storage_dump_main.c
849	@@ -0,0 +1,169 @@
850	+#include "storage/record.h"
851	+
852	+#include <errno.h>
853	+#include <inttypes.h>
854	+#include <stdio.h>
855	+#include <string.h>
856	+
857	+/*
858	+ * storage-dump program: read a storage log record by record through
859	+ * storage_record_decode and print every field, so what reached storage
860	+ * can be checked by hand. Read-only; it never repairs a file.
861	+ *
862	+ * Each record line starts with SIMULATED or LIVE, from that record's own
863	+ * SIMULATED flag. The summary checks that every record decoded, the
864	+ * sequence numbers rise by exactly one, and the file is whole records.
865	+ *
866	+ * Exit status: 0 if every check passed, 1 if any failed or the file could
867	+ * not be read, 2 for a usage error.
868	+ */
869	+
870	+/* type_name: a record type as text. */
871	+static const char *type_name(uint8_t record_type)
872	+{
873	+    switch (record_type) {
874	+    case STORAGE_RECORD_TYPE_LIGHT: return "light";
875	+    case STORAGE_RECORD_TYPE_SOIL: return "soil";
876	+    case STORAGE_RECORD_TYPE_START: return "START";
877	+    default: return "UNKNOWN";
878	+    }
879	+}
880	+
881	+/* decode_name: a storage_record_decode result as text. */
882	+static const char *decode_name(storage_record_result r)
883	+{
884	+    switch (r) {
885	+    case STORAGE_RECORD_OK: return "OK";
886	+    case STORAGE_RECORD_ARGUMENT: return "ARGUMENT";
887	+    case STORAGE_RECORD_BAD_MAGIC: return "BAD_MAGIC";
888	+    case STORAGE_RECORD_BAD_VERSION: return "BAD_VERSION";
889	+    case STORAGE_RECORD_BAD_CRC: return "BAD_CRC";
890	+    default: return "UNKNOWN";
891	+    }
892	+}
893	+
894	+/* unit_name: the unit of a record's sensor_value. */
895	+static const char *unit_name(uint8_t record_type)
896	+{
897	+    switch (record_type) {
898	+    case STORAGE_RECORD_TYPE_LIGHT: return "millilux";
899	+    case STORAGE_RECORD_TYPE_SOIL: return "raw_counts";
900	+    default: return "none";
901	+    }
902	+}
903	+
904	+/* print_record: one decoded record, every field. */
905	+static void print_record(uint64_t index, const storage_record *r)
906	+{
907	+    printf("%s record=%" PRIu64 " type=%s sequence=%" PRIu64
908	+           " valid=%d simulated=%d clock_untrusted=%d time_unavailable=%d"
909	+           " wall_ns=%" PRIu64 " mono_ns=%" PRIu64 " value=%" PRIu32
910	+           " unit=%s i2c_status=%u failure_stage=%u errno=%u"
911	+           " source_sequence=%" PRIu32 " crc=OK\n",
912	+           (r->flags & STORAGE_FLAG_SIMULATED) ? "SIMULATED" : "LIVE",
913	+           index, type_name(r->record_type), r->sequence,
914	+           (r->flags & STORAGE_FLAG_VALID) != 0,
915	+           (r->flags & STORAGE_FLAG_SIMULATED) != 0,
916	+           (r->flags & STORAGE_FLAG_CLOCK_UNTRUSTED) != 0,
917	+           (r->flags & STORAGE_FLAG_TIME_UNAVAILABLE) != 0,
918	+           r->wall_clock_ns, r->monotonic_ns, r->sensor_value,
919	+           unit_name(r->record_type), (unsigned)r->i2c_status,
920	+           (unsigned)r->failure_stage, (unsigned)r->os_errno,
921	+           r->source_sequence);
922	+}
923	+
924	+/* main: dump one file. */
925	+int main(int argc, char **argv)
926	+{
927	+    uint8_t buf[STORAGE_RECORD_SIZE_BYTES];
928	+    storage_record rec;
929	+    uint64_t index = 0;
930	+    uint64_t counts[4] = {0, 0, 0, 0};   /* by type; 0 is unknown */
931	+    uint64_t valid_counts[4] = {0, 0, 0, 0};
932	+    uint64_t bad = 0;
933	+    uint64_t sequence_breaks = 0;
934	+    uint64_t expect_sequence = 0;
935	+    size_t tail_bytes = 0;
936	+    int read_failed = 0;
937	+    int read_errno = 0;
938	+    FILE *f;
939	+    int ok;
940	+
941	+    if (argc != 2 || argv[1] == NULL || argv[1][0] == '\0' ||
942	+        strcmp(argv[1], "--help") == 0) {
943	+        fprintf(argc == 2 && strcmp(argv[1], "--help") == 0 ? stdout
944	+                                                            : stderr,
945	+                "usage: %s FILE\nPrint every record of a storage log and "
946	+                "check it.\n", argc > 0 ? argv[0] : "storage-dump");
947	+        return argc == 2 && strcmp(argv[1], "--help") == 0 ? 0 : 2;
948	+    }
949	+
950	+    errno = 0;
951	+    f = fopen(argv[1], "rb");
952	+    if (f == NULL) {
953	+        fprintf(stderr, "%s: cannot open '%s': %s\n", argv[0], argv[1],
954	+                strerror(errno != 0 ? errno : EIO));
955	+        return 1;
956	+    }
957	+    for (;;) {
958	+        size_t n = fread(buf, 1, sizeof buf, f);
959	+        storage_record_result dr;
960	+
961	+        if (n < sizeof buf) {
962	+            if (ferror(f)) {
963	+                read_failed = 1;
964	+                read_errno = errno;
965	+            }
966	+            tail_bytes = n;
967	+            break;
968	+        }
969	+        dr = storage_record_decode(buf, &rec);
970	+        if (dr != STORAGE_RECORD_OK) {
971	+            printf("BAD record=%" PRIu64 " decode=%s\n", index,
972	+                   decode_name(dr));
973	+            bad++;
974	+        } else {
975	+            unsigned t = rec.record_type <= STORAGE_RECORD_TYPE_START
976	+                             ? rec.record_type : 0;
977	+            print_record(index, &rec);
978	+            counts[t]++;
979	+            if (rec.flags & STORAGE_FLAG_VALID) {
980	+                valid_counts[t]++;
981	+            }
982	+            if (t == 0) {
983	+                bad++;
984	+            }
985	+            if (index > 0 && rec.sequence != expect_sequence) {
986	+                sequence_breaks++;
987	+            }
988	+            expect_sequence = rec.sequence + 1;
989	+        }
990	+        index++;
991	+    }
992	+    if (fclose(f) != 0) {
993	+        fprintf(stderr, "%s: closing '%s' failed: %s\n", argv[0], argv[1],
994	+                strerror(errno != 0 ? errno : EIO));
995	+        read_failed = 1;
996	+    }
997	+    if (read_failed) {
998	+        fprintf(stderr, "%s: reading '%s' failed: %s\n", argv[0], argv[1],
999	+                strerror(read_errno != 0 ? read_errno : EIO));
1000	+    }
1001	+
1002	+    ok = !read_failed && bad == 0 && sequence_breaks == 0 &&
1003	+         tail_bytes == 0 && index > 0;
1004	+    printf("summary records=%" PRIu64 " start=%" PRIu64 " light=%" PRIu64
1005	+           " light_valid=%" PRIu64 " soil=%" PRIu64 " soil_valid=%" PRIu64
1006	+           " bad=%" PRIu64 " sequence_breaks=%" PRIu64
1007	+           " partial_tail_bytes=%zu result=%s\n",
1008	+           index, counts[STORAGE_RECORD_TYPE_START],
1009	+           counts[STORAGE_RECORD_TYPE_LIGHT],
1010	+           valid_counts[STORAGE_RECORD_TYPE_LIGHT],
1011	+           counts[STORAGE_RECORD_TYPE_SOIL],
1012	+           valid_counts[STORAGE_RECORD_TYPE_SOIL], bad, sequence_breaks,
1013	+           tail_bytes, ok ? "PASS" : "FAIL");
1014	+    if (fflush(stdout) != 0 || ferror(stdout)) {
1015	+        return 1;
1016	+    }
1017	+    return ok ? 0 : 1;
1018	+}
