 11	#define STORAGE_FLAGS_KNOWN                                         \
 12	    (STORAGE_FLAG_VALID | STORAGE_FLAG_SIMULATED |                  \
 13	     STORAGE_FLAG_CLOCK_UNTRUSTED | STORAGE_FLAG_TIME_UNAVAILABLE)
 14	#define LOG_FILE_MODE 0644
 15	
 16	/* real_open_dir: open a directory read-only so it can be fsync'd. */
 17	static int real_open_dir(const char *path)
 18	{
 19	    return open(path, O_RDONLY | O_DIRECTORY | O_CLOEXEC);
 20	}
 21	
 22	/* real_open_append_at: create or open dir_fd/name for appending. It is
 23	 * opened read-write only so open can pread the last record; O_APPEND
 24	 * still sends every write to the end. */
 25	static int real_open_append_at(int dir_fd, const char *name)
 26	{
 27	    return openat(dir_fd, name, O_RDWR | O_CREAT | O_APPEND | O_CLOEXEC,
 28	                  LOG_FILE_MODE);
 29	}
 30	
 31	/* real_fdatasync: fdatasync on Linux, the target. macOS, used only to run
 32	 * the tests, does not declare fdatasync, so it uses the stronger fsync. */
 33	static int real_fdatasync(int fd)
 34	{
 35	#ifdef __APPLE__
 36	    return fsync(fd);
 37	#else
 38	    return fdatasync(fd);
 39	#endif
 40	}
 41	
 42	const storage_log_sys storage_log_real_sys = {
 43	    real_open_dir, real_open_append_at, fstat, pread, write,
 44	    real_fdatasync, fsync, close
 45	};
 46	
 47	/* log_result: build a writer result. */
 48	static storage_log_result log_result(storage_log_status status,
 49	                                     storage_log_stage stage, int os_errno)
 50	{
 51	    storage_log_result result = {status, stage, os_errno};
 52	    return result;
 53	}
 54	
 55	/* log_ok: the success result. */
 56	static storage_log_result log_ok(void)
 57	{
 58	    return log_result(STORAGE_LOG_OK, STORAGE_LOG_STAGE_NONE, 0);
 59	}
 60	
 61	/* log_status: a result with no failing system call. */
 62	static storage_log_result log_status(storage_log_status status)
 63	{
 64	    return log_result(status, STORAGE_LOG_STAGE_NONE, 0);
 65	}
 66	
 67	/* log_os_error: a failed system call at stage, with its errno. */
 68	static storage_log_result log_os_error(storage_log_stage stage,
 69	                                       int os_errno)
 70	{
 71	    return log_result(STORAGE_LOG_OS_ERROR, stage, os_errno);
 72	}
 73	
 74	/* check_open: reject a NULL or closed writer, or one that has failed. */
 75	static storage_log_result check_open(const storage_log_writer *w)
 76	{
 77	    if (w == NULL)
 78	        return log_status(STORAGE_LOG_ARGUMENT);
 79	    if (!w->is_open)
 80	        return log_status(STORAGE_LOG_NOT_OPEN);
 81	    if (w->failed)
 82	        return log_status(STORAGE_LOG_FAILED);
 83	    return log_ok();
 84	}
 85	
 86	/* record_is_known: the record type is known and no reserved flag is set. */
 87	static int record_is_known(const storage_record *rec)
 88	{
 89	    return rec->record_type >= STORAGE_RECORD_TYPE_LIGHT &&
 90	           rec->record_type <= STORAGE_RECORD_TYPE_START &&
 91	           (rec->flags & ~STORAGE_FLAGS_KNOWN) == 0;
 92	}
 93	
 94	/* name_is_simulated: file_name starts with STORAGE_LOG_SIMULATED_PREFIX. */
 95	static int name_is_simulated(const char *file_name)
 96	{
 97	    return strncmp(file_name, STORAGE_LOG_SIMULATED_PREFIX,
 98	                   sizeof STORAGE_LOG_SIMULATED_PREFIX - 1) == 0;
 99	}
100	
101	/*
102	 * check_tail: read and decode the last record of a non-empty file, and
103	 * check this writer continues it: the same SIMULATED flag, and
104	 * next_sequence one past its sequence. EINTR is retried.
105	 */
106	static storage_log_result check_tail(int fd, off_t size_bytes,
107	                                     uint64_t next_sequence, int simulated,
108	                                     const storage_log_sys *sys)
109	{
110	    uint8_t tail[STORAGE_RECORD_SIZE_BYTES];
111	    storage_record last;
112	    ssize_t n;
113	
114	    do {
115	        n = sys->pread(fd, tail, sizeof tail,
116	                       size_bytes - STORAGE_RECORD_SIZE_BYTES);
117	    } while (n < 0 && errno == EINTR);
118	    if (n < 0)
119	        return log_os_error(STORAGE_LOG_STAGE_READ_TAIL, errno);
120	    if ((size_t)n != sizeof tail ||
121	        storage_record_decode(tail, &last) != STORAGE_RECORD_OK ||
122	        !record_is_known(&last))
123	        return log_status(STORAGE_LOG_BAD_TAIL);
124	    if (((last.flags & STORAGE_FLAG_SIMULATED) != 0) != simulated)
125	        return log_status(STORAGE_LOG_SIMULATED_MISMATCH);
126	    if (last.sequence == UINT64_MAX || last.sequence + 1 != next_sequence)
127	        return log_status(STORAGE_LOG_SEQUENCE);
128	    return log_ok();
129	}
130	
131	/*
132	 * storage_log_open_sys: open the directory, open or create the file in it,
133	 * check the file holds whole records and that this writer continues its
134	 * last record, sync the directory so the name is durable, then close the
135	 * directory. On failure everything opened here is closed and the first
136	 * error is returned; cleanup close errors after an earlier error are not
137	 * reported, because the earlier error is the cause.
138	 */
139	storage_log_result storage_log_open_sys(storage_log_writer *w,
140	                                        const char *dir_path,
141	                                        const char *file_name,
142	                                        uint64_t next_sequence,
143	                                        int simulated,
144	                                        const storage_log_sys *sys)
145	{
146	    storage_log_result result = log_ok();
147	    struct stat st;
148	    int dir_fd;
149	    int file_fd = -1;
150	
151	    if (w == NULL || dir_path == NULL || file_name == NULL || sys == NULL)
152	        return log_status(STORAGE_LOG_ARGUMENT);
153	    if (w->is_open)
154	        return log_status(STORAGE_LOG_ALREADY_OPEN);
155	    w->fd = -1;
156	    if (name_is_simulated(file_name) != (simulated != 0))
157	        return log_status(STORAGE_LOG_SIMULATED_MISMATCH);
158	
159	    dir_fd = sys->open_dir(dir_path);
160	    if (dir_fd < 0)
161	        return log_os_error(STORAGE_LOG_STAGE_OPEN_DIR, errno);
162	
163	    file_fd = sys->open_append_at(dir_fd, file_name);
164	    if (file_fd < 0) {
165	        result = log_os_error(STORAGE_LOG_STAGE_OPEN_FILE, errno);
166	        goto close_dir;
167	    }
168	    if (sys->fstat(file_fd, &st) != 0) {
169	        result = log_os_error(STORAGE_LOG_STAGE_STAT, errno);
170	        goto close_file;
171	    }
172	    if (st.st_size < 0 || st.st_size % STORAGE_RECORD_SIZE_BYTES != 0) {
173	        result = log_status(STORAGE_LOG_MISALIGNED);
174	        goto close_file;
175	    }
176	    if (st.st_size > 0) {
177	        result = check_tail(file_fd, st.st_size, next_sequence,
178	                            simulated != 0, sys);
179	        if (result.status != STORAGE_LOG_OK)
180	            goto close_file;
181	    }
182	    if (sys->fsync(dir_fd) != 0) {
183	        result = log_os_error(STORAGE_LOG_STAGE_SYNC_DIR, errno);
184	        goto close_file;
185	    }
186	    if (sys->close(dir_fd) != 0) {
187	        result = log_os_error(STORAGE_LOG_STAGE_CLOSE_DIR, errno);
188	        (void)sys->close(file_fd);  /* not retried; result has the cause */
189	        return result;
190	    }
191	
192	    w->is_open = 1;
193	    w->fd = file_fd;
194	    w->simulated = simulated != 0;
195	    w->failed = 0;
196	    w->next_sequence = next_sequence;
197	    w->file_size_bytes = (uint64_t)st.st_size;
198	    w->buffered_records = 0;
199	    w->oldest_buffered_ns = 0;
200	    w->sys = sys;
201	    return result;
202	
203	close_file:
204	    (void)sys->close(file_fd);
205	close_dir:
206	    (void)sys->close(dir_fd);
207	    return result;
208	}
209	
210	/* storage_log_open: storage_log_open_sys with the real system calls. */
211	storage_log_result storage_log_open(storage_log_writer *w,
212	                                    const char *dir_path,
213	                                    const char *file_name,
214	                                    uint64_t next_sequence, int simulated)
215	{
216	    return storage_log_open_sys(w, dir_path, file_name, next_sequence,
217	                                simulated, &storage_log_real_sys);
218	}
219	
220	/*
221	 * storage_log_flush: write the whole batch, retrying EINTR and continuing
222	 * after a short write, then fdatasync. Any other failure marks the writer
223	 * failed; nothing is retried after that (see log_writer.h).
224	 */
225	storage_log_result storage_log_flush(storage_log_writer *w)
226	{
227	    storage_log_result result = check_open(w);
228	    size_t len_bytes;
229	    size_t done_bytes = 0;
230	
231	    if (result.status != STORAGE_LOG_OK || w->buffered_records == 0)
232	        return result;
233	
234	    len_bytes = w->buffered_records * STORAGE_RECORD_SIZE_BYTES;
235	    while (done_bytes < len_bytes) {
236	        ssize_t n = w->sys->write(w->fd, w->buffer + done_bytes,
237	                                  len_bytes - done_bytes);
238	
239	        if (n < 0 && errno == EINTR)
240	            continue;
241	        if (n <= 0) {
242	            /* write() returning 0 for a nonzero length has no errno. */
243	            w->failed = 1;
244	            return log_os_error(STORAGE_LOG_STAGE_WRITE, n < 0 ? errno : 0);
245	        }
246	        done_bytes += (size_t)n;
247	        w->file_size_bytes += (uint64_t)n;
248	    }
249	
250	    if (w->sys->fdatasync(w->fd) != 0) {
251	        w->failed = 1;
252	        return log_os_error(STORAGE_LOG_STAGE_SYNC, errno);
253	    }
254	    w->buffered_records = 0;
255	    return result;
256	}
257	
258	/* batch_due: records are buffered and the oldest has waited at least
259	 * STORAGE_LOG_FLUSH_INTERVAL_NS by now_monotonic_ns. */
260	static int batch_due(const storage_log_writer *w, uint64_t now_monotonic_ns)
261	{
262	    return w->buffered_records > 0 &&
263	           now_monotonic_ns >= w->oldest_buffered_ns &&
264	           now_monotonic_ns - w->oldest_buffered_ns >=
265	               STORAGE_LOG_FLUSH_INTERVAL_NS;
266	}
267	
268	/* storage_log_append: check rec, encode it into the batch, and flush the
269	 * batch when it is full or its oldest record is due. */
270	storage_log_result storage_log_append(storage_log_writer *w,
271	                                      const storage_record *rec,
272	                                      uint64_t now_monotonic_ns)
273	{
274	    storage_log_result result;
275	    int rec_simulated;
276	
277	    if (w == NULL || rec == NULL)
278	        return log_status(STORAGE_LOG_ARGUMENT);
279	    result = check_open(w);
280	    if (result.status != STORAGE_LOG_OK)
281	        return result;
282	
283	    if (!record_is_known(rec))
284	        return log_status(STORAGE_LOG_BAD_RECORD);
285	    rec_simulated = (rec->flags & STORAGE_FLAG_SIMULATED) != 0;
286	    if (rec_simulated != w->simulated)
287	        return log_status(STORAGE_LOG_SIMULATED_MISMATCH);
288	    if (rec->sequence != w->next_sequence)
289	        return log_status(STORAGE_LOG_SEQUENCE);
290	
291	    /* Cannot fail: both pointers were checked above. */
292	    (void)storage_record_encode(
293	        rec, w->buffer + w->buffered_records * STORAGE_RECORD_SIZE_BYTES);
294	    if (w->buffered_records == 0)
295	        w->oldest_buffered_ns = now_monotonic_ns;
296	    w->buffered_records++;
297	    w->next_sequence++;
298	
299	    if (w->buffered_records == STORAGE_LOG_BATCH_RECORDS ||
300	        batch_due(w, now_monotonic_ns))
301	        return storage_log_flush(w);
302	    return result;
303	}
304	
305	/* storage_log_flush_if_due: flush once the oldest buffered record has
306	 * waited STORAGE_LOG_FLUSH_INTERVAL_NS. */
307	storage_log_result storage_log_flush_if_due(storage_log_writer *w,
308	                                            uint64_t now_monotonic_ns)
309	{
310	    storage_log_result result = check_open(w);
311	
312	    if (result.status != STORAGE_LOG_OK || !batch_due(w, now_monotonic_ns))
313	        return result;
314	    return storage_log_flush(w);
315	}
316	
317	/* storage_log_close: flush unless failed, then close the file once.
318	 * close() is not retried on EINTR: on Linux the descriptor is already
319	 * released, and retrying could close a descriptor reused by another
320	 * thread or process. */
321	storage_log_result storage_log_close(storage_log_writer *w)
322	{
323	    storage_log_result result;
324	
325	    if (w == NULL)
326	        return log_status(STORAGE_LOG_ARGUMENT);
327	    if (!w->is_open)
328	        return log_status(STORAGE_LOG_NOT_OPEN);
329	
330	    result = w->failed ? log_status(STORAGE_LOG_FAILED)
331	                       : storage_log_flush(w);
332	    if (w->sys->close(w->fd) != 0 && result.status == STORAGE_LOG_OK)
333	        result = log_os_error(STORAGE_LOG_STAGE_CLOSE_FILE, errno);
334	    w->is_open = 0;
335	    w->fd = -1;
336	    return result;
337	}

