   242	/* capture_usage: the --help text. */
   243	void capture_usage(FILE *out, const char *program)
   244	{
   245	    fprintf(out,
   246	        "usage: %s --sensor light|soil --bus N --store-dir DIR\n"
   247	        "       [--addr ADDR] [--tick-ms N] [--every N]\n"
   248	        "\n"
   249	        "Capture one sensor on /dev/i2c-N. Run one process per sensor.\n"
   250	        "\n"
   251	        "  --sensor light|soil  which sensor this process captures\n"
   252	        "  --bus N              I2C bus number. --bus is required; there is\n"
   253	        "                       no default, because initialization writes\n"
   254	        "                       to the bus.\n"
   255	        "  --addr ADDR          light 0x23 (default) or 0x5c; soil 0x36\n"
   256	        "                       (default) to 0x39\n"
   257	        "  --tick-ms N          heartbeat tick, %u to %u ms\n"
   258	        "                       (PROPOSED default 10000)\n"
   259	        "  --every N            ticks between attempts, 1 to %u\n"
   260	        "                       (PROPOSED default: light 1, soil 6)\n"
   261	        "  --store-dir DIR      existing directory for this sensor's storage\n"
   262	        "                       log. TEMPORARY per-sensor integration until\n"
   263	        "                       the hub exists: use one directory per sensor;\n"
   264	        "                       sequence numbers are per process, not\n"
   265	        "                       hub-wide. A previous run's log in DIR is\n"
   266	        "                       refused (no recovery yet).\n"
   267	        "  --help               show this text\n"
   268	        "\n"
   269	        "Numbers are decimal; hex only for --addr (0x23). A leading 0 is\n"
   270	        "decimal. The rates, backoff and reinitialization policy are\n"
   271	        "PROPOSED values awaiting agreement, not requirements.\n"
   272	        "\n"
   273	        "Exit status: 0 after a requested stop, 1 for any failure, 2 for a\n"
   274	        "usage error.\n",
   275	        program, CAPTURE_ARGS_TICK_MS_MIN, CAPTURE_ARGS_TICK_MS_MAX,
   276	        CAPTURE_ARGS_EVERY_MAX);
   277	}
