   280	int capture_exit_status(capture_exit result)
   281	{
   282	    if (result == CAPTURE_EXIT_STOPPED) {
   283	        return 0;
   284	    }
   285	    return result == CAPTURE_EXIT_USAGE ? 2 : 1;
