390	/* read_records: decode every record of the log; return the count. */
391	static size_t read_records(storage_record *out, size_t cap)
392	{
393	    char path[PATH_CAP];
394	    uint8_t buf[STORAGE_RECORD_SIZE_BYTES];
395	    FILE *fp;
396	    size_t n = 0;
397	    size_t got;
398	
399	    assert(snprintf(path, sizeof path, "%s/%s", temp_dir,
400	                    CAPTURE_STORE_SIMULATED_FILE_NAME) > 0);
401	    fp = fopen(path, "rb");
402	    assert(fp != NULL);
403	    while ((got = fread(buf, 1, sizeof buf, fp)) == sizeof buf) {
404	        assert(n < cap);
405	        assert(storage_record_decode(buf, &out[n]) == STORAGE_RECORD_OK);
406	        n++;
407	    }
408	    assert(got == 0 && !ferror(fp));   /* whole records only */
409	    assert(fclose(fp) == 0);
410	    return n;
411	}
