456	/*
457	 * test_light_end_to_end: START plus three light records reach the file in
458	 * order, gapless from 1, each SIMULATED, VALID and CLOCK_UNTRUSTED, with
459	 * the capture counter in source_sequence.
460	 */
461	static void test_light_end_to_end(void)
462	{
463	    static fake f;
464	    static capture_store st;
465	    storage_record recs[MAX_FILE_RECORDS];
466	    char text[LOG_CAP];
467	    capture_config cfg;
468	    FILE *log = tmpfile();
469	    size_t n;
470	    size_t i;
471	
472	    assert(log != NULL);
473	    make_temp_dir();
474	    memset(&f, 0, sizeof f);
475	    f.now_ns = ANCHOR_NS;
476	    f.stop_after_heartbeats = 3;
477	    script_light(&f, 3);
478	    capture_config_proposed(&cfg, CAPTURE_SENSOR_LIGHT, 1, 0x23);
479	
480	    assert(run_capture(&f, &cfg, log, &st) == CAPTURE_EXIT_STOPPED);
481	    assert(f.mock.next_step == f.step_count && !f.mock.mismatch);
482	    assert(capture_store_close(&st) == 0);
483	
484	    n = read_records(recs, COUNT_OF(recs));
485	    assert(n == 4);
486	    assert(recs[0].record_type == STORAGE_RECORD_TYPE_START);
487	    for (i = 0; i < n; i++) {
488	        assert(recs[i].sequence == i + 1);
489	        assert(recs[i].flags & STORAGE_FLAG_SIMULATED);
490	        assert(recs[i].flags & STORAGE_FLAG_CLOCK_UNTRUSTED);
491	    }
492	    for (i = 1; i < n; i++) {
493	        assert(recs[i].record_type == STORAGE_RECORD_TYPE_LIGHT);
494	        assert(recs[i].flags & STORAGE_FLAG_VALID);
495	        assert(recs[i].sensor_value == 10000);
496	        assert(recs[i].source_sequence == i);
497	        /* One sample per 10 s tick; START shares tick 0's fake time. */
498	        assert(recs[i].monotonic_ns ==
499	               (uint64_t)(ANCHOR_NS + (int64_t)(i - 1) *
500	                                          CAPTURE_PROPOSED_TICK_PERIOD_NS));
501	    }
502	    assert(recs[0].monotonic_ns == (uint64_t)ANCHOR_NS);
503	
504	    read_log(log, text, sizeof text);
505	    assert_every_line_simulated(text);
506	    assert(strstr(text, "event=store_open storage=temporary-per-sensor") !=
507	           NULL);
508	    assert(strstr(text, "sequence_scope=this_process_only") != NULL);
509	    assert(strstr(text, "event=stored storage=temporary-per-sensor "
510	                        "type=light sequence=4 source_sequence=3 valid=1")
511	           != NULL);
512	    assert(strstr(text, "event=store_close") != NULL);
513	    assert(fclose(log) == 0);
514	    remove_temp();
515	}
