 59	    s.sensor = CAPTURE_SENSOR_LIGHT;
 60	    s.sequence = 7;
 61	    s.is_simulated = 1;
 62	    s.phase = CAPTURE_PHASE_MEASURE;
 63	    s.valid = 1;
 64	    s.unit = CAPTURE_UNIT_MILLILUX;
 65	    s.value = 12500;
