217	/* The fake world: a scripted mock device, a fake clock, a stop count. */
218	typedef struct {
219	    i2c_mock_step steps[MAX_STEPS];
220	    size_t step_count;
221	    i2c_mock mock;
222	    int64_t now_ns;
223	    unsigned heartbeats;
224	    unsigned stop_after_heartbeats;
