231	/* add: append one scripted step. */
232	static void add(fake *f, i2c_mock_op op, const uint8_t *bytes, size_t len,
233	                uint32_t min_wait_us)
234	{
235	    i2c_mock_step step = {op, bytes, len, len, 0, min_wait_us};
236	
237	    assert(f->step_count < MAX_STEPS);
238	    f->steps[f->step_count++] = step;
239	}
