241	/* script_light: init, then n measurements of 12 counts. */
242	static void script_light(fake *f, unsigned n)
243	{
244	    add(f, I2C_MOCK_WRITE, cmd_power_on, 1, 0);
245	    add(f, I2C_MOCK_WRITE, cmd_mtreg_high, 1, 0);
246	    add(f, I2C_MOCK_WRITE, cmd_mtreg_low, 1, 0);
247	    while (n-- > 0) {
248	        add(f, I2C_MOCK_WRITE, cmd_one_time_h, 1, 0);
249	        add(f, I2C_MOCK_WAIT, NULL, 0, 180000);
250	        add(f, I2C_MOCK_READ, light_raw_12, 2, 0);
251	    }
252	}
253	
254	/* script_soil: init, then n measurements of 500 counts. */
255	static void script_soil(fake *f, unsigned n)
256	{
257	    add(f, I2C_MOCK_WRITE, cmd_reset, sizeof cmd_reset, 0);
258	    add(f, I2C_MOCK_WAIT, NULL, 0, 500000);
259	    add(f, I2C_MOCK_WRITE, cmd_hw_id, sizeof cmd_hw_id, 0);
260	    add(f, I2C_MOCK_WAIT, NULL, 0, 8000);
261	    add(f, I2C_MOCK_READ, id_samd, 1, 0);
262	    while (n-- > 0) {
263	        add(f, I2C_MOCK_WRITE, cmd_touch0, sizeof cmd_touch0, 0);
264	        add(f, I2C_MOCK_WAIT, NULL, 0, 5000);
265	        add(f, I2C_MOCK_READ, soil_500, 2, 0);
266	    }
267	}
