269	/* fake_open: open the scripted mock (always SIMULATED). */
270	static i2c_result fake_open(void *ctx, i2c_device *dev, unsigned bus_number,
271	                            uint8_t address_7bit, int *cleanup_errno)
272	{
273	    fake *f = ctx;
274	    i2c_result r = {I2C_STATUS_OK, 0, 0, 0};
275	
276	    (void)bus_number;
277	    *cleanup_errno = 0;
278	    assert(i2c_mock_open(&f->mock, dev, address_7bit, f->steps,
279	                         f->step_count) == I2C_STATUS_OK);
280	    return r;
281	}
