283	/* fake_read_clock: wall = WALL_OFFSET + monotonic. */
284	static int fake_read_clock(void *ctx, capture_clock clock,
285	                           struct timespec *out)
286	{
287	    fake *f = ctx;
288	    int64_t ns = f->now_ns;
289	
290	    if (clock == CAPTURE_CLOCK_WALL) {
291	        ns += WALL_OFFSET_NS;
292	    }
293	    out->tv_sec = (time_t)(ns / SEC);
294	    out->tv_nsec = (long)(ns % SEC);
295	    return 0;
296	}
