298	/* fake_sleep_until: jump the fake clock to the deadline. */
299	static int fake_sleep_until(void *ctx, int64_t deadline_mono_ns)
300	{
301	    fake *f = ctx;
302	
303	    if (deadline_mono_ns > f->now_ns) {
304	        f->now_ns = deadline_mono_ns;
305	    }
306	    return 0;
307	}
