309	/* fake_trust: always untrusted, as on the Pi with no network. */
310	static capture_clock_trust fake_trust(void *ctx, int *err)
311	{
312	    (void)ctx;
313	    *err = 0;
314	    return CAPTURE_CLOCK_UNTRUSTED;
315	}
