325	/* file_size: bytes in temp_dir/name, or -1 if it does not exist. */
326	static long file_size(const char *name)
327	{
328	    char path[PATH_CAP];
329	    FILE *fp;
330	    long n;
331	
332	    assert(snprintf(path, sizeof path, "%s/%s", temp_dir, name) > 0);
333	    fp = fopen(path, "rb");
334	    if (fp == NULL) {
335	        return -1;
336	    }
337	    assert(fseek(fp, 0, SEEK_END) == 0);
338	    n = ftell(fp);
339	    assert(fclose(fp) == 0);
