343	/* count_heartbeat: the store's heartbeat sink, plus a count and size. */
344	static int count_heartbeat(void *ctx, const capture_heartbeat *h)
345	{
346	    fake *f = ctx;
347	    int err = capture_store_emit_heartbeat(f->store, h);
348	
349	    assert(f->heartbeats < COUNT_OF(f->file_bytes_at_heartbeat));
