425	/* every_line_simulated: every text line is labelled SIMULATED. */
426	static void assert_every_line_simulated(const char *text)
427	{
428	    const char *line = text;
429	
430	    while (*line != '\0') {
431	        assert(strncmp(line, "SIMULATED ", 10) == 0);
432	        line = strchr(line, '\n');
433	        assert(line != NULL);
434	        line++;
