438	/* run_capture: open the store, run the core, return the exit. */
439	static capture_exit run_capture(fake *f, const capture_config *cfg,
440	                                FILE *log, capture_store *st)
441	{
442	    capture_env env = {fake_open, fake_read_clock, fake_sleep_until,
443	                       fake_trust, fake_stop, NULL, 1};
444	    capture_sink sink = {forward_sample, count_heartbeat, NULL};
445	    capture_outcome out;
