447	
448	    env.ctx = f;
449	    sink.ctx = f;
450	    f->store = st;
451	    assert(capture_store_open(st, log, temp_dir, cfg, &env) == 0);
452	    e = capture_run(cfg, &env, &sink, &out);
453	    return e;
