517	/*
518	 * test_soil_flushed_within_deadline: a soil record (every 6th tick) is on
519	 * disk by the heartbeat before it would be 60 s old, without waiting for
520	 * close.
521	 */
522	static void test_soil_flushed_within_deadline(void)
523	{
524	    static fake f;
525	    static capture_store st;
526	    storage_record recs[MAX_FILE_RECORDS];
527	    char text[LOG_CAP];
528	    capture_config cfg;
529	    FILE *log = tmpfile();
530	    unsigned i;
531	
532	    assert(log != NULL);
533	    make_temp_dir();
534	    memset(&f, 0, sizeof f);
535	    f.now_ns = ANCHOR_NS;
536	    f.stop_after_heartbeats = 7;
537	    script_soil(&f, 2);
538	    capture_config_proposed(&cfg, CAPTURE_SENSOR_SOIL, 1, 0x36);
539	
540	    assert(run_capture(&f, &cfg, log, &st) == CAPTURE_EXIT_STOPPED);
541	    assert(f.mock.next_step == f.step_count && !f.mock.mismatch);
542	
543	    /*
544	     * START alone until the sample's batch is due. The fake clock does not
545	     * advance during mock waits, so sample 1 is appended at tick 0's time;
546	     * at the tick-5 heartbeat it would be 60 s old by tick 6, so it is
547	     * flushed then, 50 s after it was taken.
548	     */
549	    for (i = 0; i < 5; i++) {
550	        assert(f.file_bytes_at_heartbeat[i] == STORAGE_RECORD_SIZE_BYTES);
551	    }
552	    assert(f.file_bytes_at_heartbeat[5] == 2 * STORAGE_RECORD_SIZE_BYTES);
553	    assert(f.file_bytes_at_heartbeat[6] == 2 * STORAGE_RECORD_SIZE_BYTES);
554	
555	    assert(capture_store_close(&st) == 0);
556	    assert(read_records(recs, COUNT_OF(recs)) == 3);
557	    assert(recs[1].record_type == STORAGE_RECORD_TYPE_SOIL &&
558	           recs[1].sensor_value == 500 && recs[1].source_sequence == 1);
559	    assert(recs[1].monotonic_ns == (uint64_t)ANCHOR_NS);
560	    assert(recs[2].record_type == STORAGE_RECORD_TYPE_SOIL &&
561	           recs[2].sequence == 3 && recs[2].source_sequence == 2);
562	
563	    read_log(log, text, sizeof text);
564	    assert_every_line_simulated(text);
565	    assert(strstr(text, "event=store_flush storage=temporary-per-sensor "
566	                        "records=1 reason=deadline") != NULL);
567	    assert(fclose(log) == 0);
568	    remove_temp();
569	}
