571	/*
572	 * test_previous_log_refused: a second run into the same directory is
573	 * refused (no recovery yet), logged, and leaves the old file unchanged.
574	 */
575	static void test_previous_log_refused(void)
576	{
577	    static fake f;
578	    static capture_store st;
579	    capture_env env = {fake_open, fake_read_clock, fake_sleep_until,
580	                       fake_trust, fake_stop, NULL, 1};
581	    char text[LOG_CAP];
582	    capture_config cfg;
583	    FILE *log = tmpfile();
584	    long before;
585	
586	    assert(log != NULL);
587	    make_temp_dir();
588	    memset(&f, 0, sizeof f);
589	    f.now_ns = ANCHOR_NS;
590	    env.ctx = &f;
591	    capture_config_proposed(&cfg, CAPTURE_SENSOR_LIGHT, 1, 0x23);
592	
593	    assert(capture_store_open(&st, log, temp_dir, &cfg, &env) == 0);
594	    assert(capture_store_close(&st) == 0);
595	    before = file_size(CAPTURE_STORE_SIMULATED_FILE_NAME);
596	    assert(before == STORAGE_RECORD_SIZE_BYTES);
597	
598	    assert(capture_store_open(&st, log, temp_dir, &cfg, &env) != 0);
599	    assert(!st.writer.is_open);
600	    assert(file_size(CAPTURE_STORE_SIMULATED_FILE_NAME) == before);
601	    read_log(log, text, sizeof text);
602	    assert(strstr(text, "event=store_error storage=temporary-per-sensor "
603	                        "op=open result=SEQUENCE") != NULL);
604	    assert(fclose(log) == 0);
605	    remove_temp();
